#include <stdio.h>
#define MOD 998244353

int main() {
    int N, K;
    scanf("%d %d", &N, &K);

    int l[K], r[K];
    for (int i = 0; i < K; i++) {
        scanf("%d %d", &l[i], &r[i]);
    }

    int dp[N + 1], diff[N + 2];
    for (int i = 0; i <= N + 1; i++) {
        dp[i] = 0;
        diff[i] = 0;
    }

    dp[1] = 1;
    int sum = 0;

    for (int i = 1; i <= N; i++) {
        sum = (sum + diff[i]) % MOD;
        dp[i] = (dp[i] + sum) % MOD;

        if (i == N) break;

        for (int j = 0; j < K; j++) {
            int left = i + l[j];
            int right = i + r[j];
            if (left <= N) {
                diff[left] = (diff[left] + dp[i]) % MOD;
                if (right + 1 <= N) {
                    diff[right + 1] = (diff[right + 1] - dp[i] + MOD) % MOD;
                }
            }
        }
    }

    printf("%d\n", dp[N]);
    return 0;
}

