    vector<int64> diff(N + 2, 0); // difference array for range updates

    dp[1] = 1;
    diff[1] = (diff[1] + 1) % MOD;
    diff[2] = (diff[2] - 1 + MOD) % MOD;

    for (int i = 1; i <= N; i++) {
        if (i > 1) {
            diff[i] = (diff[i] + diff[i-1]) % MOD;
            dp[i] = (dp[i] + diff[i]) % MOD;
        }

        for (auto &seg : segments) {
            int L = seg.first, R = seg.second;
            if (i + L <= N) {
                diff[i + L] = (diff[i + L] + dp[i]) % MOD;
            }
            if (i + R + 1 <= N) {
                diff[i + R + 1] = (diff[i + R + 1] - dp[i] + MOD) % MOD;
            }
        }
    }

    cout << dp[N] % MOD << "\n";
