    for (int i = 0; i < K; i++) {
        cin >> l[i] >> r[i];
    }

    vector<long long> dp(N + 1, 0);
    vector<long long> S(N + 2, 0); // S[i] = sum of dp[1..i]

    dp[1] = 1;
    S[0] = 0;
    S[1] = 1;

    for (int i = 2; i <= N; i++) {
        dp[i] = 0;
        for (int j = 0; j < K; j++) {
            // sum dp[i-r[j]] to dp[i-l[j]]
            int lo = i - r[j]; // lower index
            int hi = i - l[j]; // upper index
            if (hi < 1) continue;
            if (lo < 1) lo = 1;
            // sum = S[hi] - S[lo-1]
            dp[i] = (dp[i] + S[hi] - S[lo - 1] + MOD) % MOD;
        }
        S[i] = (S[i - 1] + dp[i]) % MOD;
    }

    cout << dp[N] << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<pair<int,int>> seg(K);
    for (int i = 0; i < K; ++i) {
        cin >> seg[i].first >> seg[i].second;
    }

    // dp[i] = number of ways to reach cell i
    // pref[i] = dp[1] + dp[2] + ... + dp[i]
    vector<long long> dp(N + 1, 0), pref(N + 1, 0);

    dp[1] = 1;
    pref[1] = 1;

    for (int i = 2; i <= N; ++i) {
        long long ways = 0;

        for (auto [L, R] : seg) {
            int left = max(1, i - R);
            int right = i - L;
            if (right < 1) continue;

            long long add = pref[right] - (left > 1 ? pref[left - 1] : 0);
            add %= MOD;
            if (add < 0) add += MOD;

            ways += add;
            ways %= MOD;
        }

        dp[i] = ways;
        pref[i] = (pref[i - 1] + dp[i]) % MOD;
    }

    cout << dp[N] % MOD << '\n';
    return 0;
}

