import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int K = fs.nextInt();

        int[] L = new int[K];
        int[] R = new int[K];
        for (int i = 0; i < K; i++) {
            L[i] = fs.nextInt();
            R[i] = fs.nextInt();
        }

        long[] dp = new long[N + 1];
        long[] prefix = new long[N + 1];

        dp[1] = 1;
        prefix[1] = 1;

        for (int i = 2; i <= N; i++) {
            long ways = 0;

            for (int j = 0; j < K; j++) {
                int left = i - R[j];
                int right = i - L[j];

                if (right < 1) continue;
                if (left < 1) left = 1;

                long sum = prefix[right] - prefix[left - 1];
                ways += sum;
            }

            ways %= MOD;
            if (ways < 0) ways += MOD;

            dp[i] = ways;
            prefix[i] = (prefix[i - 1] + dp[i]) % MOD;
        }

        System.out.println(dp[N] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
